#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gesummv.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    {
      x[i] = (DATA_TYPE)( i % n) / n;
      for (j = 0; j < n; j++) {
	A[i][j] = (DATA_TYPE) ((i*j+1) % n) / n;
	B[i][j] = (DATA_TYPE) ((i*j+2) % n) / n;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Resolve the possibly instrumented loop bound once. */
  const int n_pb = _PB_N;

  /* Local restrict-qualified views of the 1D arrays.
   * This tells the optimizer that these pointers do not alias, which
   * improves vectorization and register allocation. */
  DATA_TYPE *restrict tmp_ = tmp;
  DATA_TYPE *restrict y_   = y;
  const DATA_TYPE *restrict x_ = x;

#pragma scop
  /* Parallelize over rows. Each iteration:
   *  - reads from shared x_, A, B
   *  - writes to distinct tmp_[i] and y_[i]
   * so there are no data races.  When compiled without OpenMP support,
   * this pragma is ignored and execution remains sequential. */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < n_pb; ++i)
    {
      /* Row pointers for better locality and fewer address computations. */
      const DATA_TYPE *restrict Ai = A[i];
      const DATA_TYPE *restrict Bi = B[i];

      /* Accumulate the two dot products for row i entirely in registers
       * (tmp_sum = sum_j A[i][j]*x[j], y_sum = sum_j B[i][j]*x[j]).
       * This avoids repeatedly reading/writing tmp[i] and y[i] inside
       * the inner loop. */
      DATA_TYPE tmp_sum = SCALAR_VAL(0.0);
      DATA_TYPE y_sum   = SCALAR_VAL(0.0);

      /* Inner product.  The GCC ivdep pragma hints that there are no
       * unexpected loop-carried dependences aside from the reductions
       * on tmp_sum and y_sum, helping vectorization. */
#pragma GCC ivdep
      for (int j = 0; j < n_pb; ++j)
        {
          DATA_TYPE xj = x_[j];
          tmp_sum += Ai[j] * xj;
          y_sum   += Bi[j] * xj;
        }

      /* Store results.  tmp_ must contain the pure A*x result to
       * preserve the original live-out semantics, and y_ combines
       * both dot products using alpha and beta. */
      tmp_[i] = tmp_sum;
      y_[i]   = alpha * tmp_sum + beta * y_sum;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
