/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv [[gnu::flatten, gnu::noinline]] (int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Optimization notes
   *
   * - Use local scalar accumulators (tmp_i, y_i) so that the inner loop
   *   operates entirely in registers and does not repeatedly store to
   *   tmp[] and y[]. This greatly reduces memory traffic.
   *
   * - Use pointer increments (a_ptr, b_ptr, x_ptr) instead of 2D
   *   indexing in the inner loop to give the compiler a very simple,
   *   contiguous access pattern that is easy to vectorize and unroll.
   *
   * - Add restrict-qualified aliases for the 1D outputs. The PolyBench
   *   macros already guarantee that A, B, x, tmp, y do not alias; making
   *   this explicit helps the compiler generate better code.
   *
   * The mathematical computation is unchanged:
   *   tmp[i] = sum_j A[i][j] * x[j]
   *   y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j]
   * The order of floating-point operations in the reductions is
   * identical to the original code (sequential accumulation in j).
   */

  DATA_TYPE * restrict tmp_ = tmp;
  DATA_TYPE * restrict y_   = y;
  const DATA_TYPE alpha_    = alpha;
  const DATA_TYPE beta_     = beta;

