  for (int i = 0; i < _PB_N; ++i)
    {
      /* Pointers to the beginning of the current rows of A and B.
       * Each row is contiguous in memory, so incrementing these
       * pointers walks linearly through A[i][*] and B[i][*]. */
      const DATA_TYPE * restrict a_ptr = &A[i][0];
      const DATA_TYPE * restrict b_ptr = &B[i][0];

      /* Pointer to the input vector x. We rescan x from the beginning
       * for each row i, which is inherent to matrix-vector multiply. */
      const DATA_TYPE * restrict x_ptr = x;

      /* Per-row accumulators kept in registers. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      for (int j = 0; j < _PB_N; ++j)
	{
	  const DATA_TYPE xj = *x_ptr++;

	  /* Fused multiply-add style operations; the compiler can map
	   * these to vector FMA instructions where available. */
	  tmp_i += (*a_ptr++) * xj;
	  y_i   += (*b_ptr++) * xj;
	}

      /* Write back the accumulated results once per row. */
      tmp_[i] = tmp_i;
      y_[i]   = alpha_ * tmp_i + beta_ * y_i;
    }
#pragma endscop

}


