 * Optimization helpers
 * -------------------------------------------------------------------------- */

/* PolyBench normally defines POLYBENCH_ALIGNMENT, but provide a safe
 * fallback for robustness. */
#ifndef POLYBENCH_ALIGNMENT
#  define POLYBENCH_ALIGNMENT 32
#endif

/* Compiler hint: the pointer is at least POLYBENCH_ALIGNMENT-byte aligned.
 * For non-GCC/Clang compilers this degrades to a no-op. */
#if defined(__GNUC__) || defined(__clang__)
#  define PB_ASSUME_ALIGNED(ptr) __builtin_assume_aligned((ptr), POLYBENCH_ALIGNMENT)
#else
#  define PB_ASSUME_ALIGNED(ptr) (ptr)
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
