  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified pointers to tell the compiler that A, B, x, y,
     and tmp do not alias. This enables more aggressive vectorization.
   - Assume alignment compatible with PolyBench allocation to generate
     aligned loads/stores.
   - Accumulate into scalar temporaries (tmp_i, y_i) kept in registers
     instead of reloading/storing tmp[i] and y[i] inside the inner loop.
   - Use row pointers (Ai, Bi) for better cache and pointer arithmetic.
   These transformations preserve the original numerical result for all
   legal PolyBench uses of this kernel.
*/
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Create local restrict-qualified views with assumed alignment.
   * This is purely a performance hint; it does not change the logical
   * layout of the data. */
  DATA_TYPE (* restrict A_)[n] =
    (DATA_TYPE (* restrict)[n]) PB_ASSUME_ALIGNED(A);
  DATA_TYPE (* restrict B_)[n] =
    (DATA_TYPE (* restrict)[n]) PB_ASSUME_ALIGNED(B);
  DATA_TYPE * restrict tmp_ =
    (DATA_TYPE * restrict) PB_ASSUME_ALIGNED(tmp);
  DATA_TYPE * restrict x_ =
    (DATA_TYPE * restrict) PB_ASSUME_ALIGNED(x);
  DATA_TYPE * restrict y_ =
    (DATA_TYPE * restrict) PB_ASSUME_ALIGNED(y);

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Use register-resident accumulators. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      /* Row pointers improve locality and simplify indexing. */
      DATA_TYPE * restrict Ai = A_[i];
      DATA_TYPE * restrict Bi = B_[i];

      /* Inner product for row i of A and B with vector x. */
      /* The compiler can now safely vectorize this loop. */
      for (j = 0; j < _PB_N; j++)
	{
	  DATA_TYPE xj = x_[j];
	  tmp_i += Ai[j] * xj;
	  y_i   += Bi[j] * xj;
	}

      /* Store final results once per element (instead of every j). */
      tmp_[i] = tmp_i;
      y_[i]   = alpha * tmp_i + beta * y_i;
    }
#pragma endscop

}


