/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i;

  /* Local aliases with restrict qualifiers to help the compiler
     with alias analysis and enable better vectorization. */
  DATA_TYPE * restrict tmp_ = tmp;
  DATA_TYPE * restrict y_   = y;
  const DATA_TYPE * restrict x_ = x;

  /* Cache _PB_N in a local variable to avoid re-evaluating the macro
     and to give the compiler a concrete loop bound. */
  const int pb_n = _PB_N;

#pragma scop
  for (i = 0; i < pb_n; i++)
    {
      /* Keep accumulators in registers to avoid repeated loads/stores
         to tmp[i] and y[i] inside the inner loop. */
      DATA_TYPE tmp_sum = SCALAR_VAL(0.0);
      DATA_TYPE y_sum   = SCALAR_VAL(0.0);

      /* Row pointers: improve locality when walking across columns. */
      const DATA_TYPE * restrict A_row = A[i];
      const DATA_TYPE * restrict B_row = B[i];

      int j;
      /* Main unrolled loop processes 4 columns per iteration.
         The unrolling is written so that the *sequential* accumulation
         order is preserved (j, j+1, j+2, j+3), maintaining the original
         floating-point semantics. */
      int limit = pb_n & ~3; /* largest multiple of 4 <= pb_n */

      for (j = 0; j < limit; j += 4)
	{
	  DATA_TYPE x0 = x_[j];
	  DATA_TYPE x1 = x_[j+1];
	  DATA_TYPE x2 = x_[j+2];
	  DATA_TYPE x3 = x_[j+3];

	  tmp_sum += A_row[j]   * x0;
	  y_sum   += B_row[j]   * x0;

	  tmp_sum += A_row[j+1] * x1;
	  y_sum   += B_row[j+1] * x1;

	  tmp_sum += A_row[j+2] * x2;
	  y_sum   += B_row[j+2] * x2;

	  tmp_sum += A_row[j+3] * x3;
	  y_sum   += B_row[j+3] * x3;
	}

      /* Handle remaining columns if pb_n is not a multiple of 4. */
      for (; j < pb_n; j++)
	{
	  DATA_TYPE xj = x_[j];
	  tmp_sum += A_row[j] * xj;
	  y_sum   += B_row[j] * xj;
	}

